import z3
import itertools

o = z3.Optimize()
A = list(range(12))
B = list(range(12, 25))
edge = {}
for a in A:
    for b in B:
        edge[(a, b)] = z3.Bool(f'e{a}_{b}')

num_edges = z3.Sum([z3.If(edge[(a,b)], 1, 0) for a in A for b in B])
o.add(num_edges >= 0)  # dummy

# no C4
for i1, i2 in itertools.combinations(range(len(A)), 2):
    a1, a2 = A[i1], A[i2]
    for j1, j2 in itertools.combinations(range(len(B)), 2):
        b1, b2 = B[j1], B[j2]
        o.add(z3.Or([z3.Not(edge[(a1, b1)]), z3.Not(edge[(a1, b2)]), z3.Not(edge[(a2, b1)]), z3.Not(edge[(a2, b2)])]))

# no C6
for a_list in itertools.combinations(A, 3):
    for b_list in itertools.combinations(B, 3):
        for perm in itertools.permutations(range(3)):
            non = [(a_list[k], b_list[perm[k]]) for k in range(3)]
            all_e = [(aa, bb) for aa in a_list for bb in b_list]
            cyc_e = [e for e in all_e if e not in non]
            o.add(z3.Or([z3.Not(edge[e]) for e in cyc_e]))

max_edges = o.maximize(num_edges)
res = o.check()
print(res)
if res == z3.sat:
    print(o.lower(max_edges))
